/**
 * File swap for in-place updates of a binary installation.
 *
 * CommonJS with Node built-ins only, because two very different callers load
 * it:
 *
 *  - `launcher.cjs` (generated by build-sea.cjs), which applies a pending
 *    update BEFORE it starts the server ("swap on start"). Nothing runs from
 *    `server/` at that point, so no file below it is held open — on Windows a
 *    live server's native addons made the rename of `server/` fail with
 *    EBUSY/EPERM. The launcher also counts failed starts after an update and
 *    restores the previous version when the new one does not come up.
 *  - `services/updateService.js`, for the legacy in-process swap (a launcher
 *    older than {@link LAUNCHER_PROTOCOL}) and for the CLI, which runs with
 *    the server stopped.
 *
 * Files in the installation root:
 *
 *  - `.update-staging/`     verified, extracted release waiting to be applied
 *  - `.update-pending.json` "apply the staged release on the next start"
 *  - `.update-attempt.json` an applied update whose server has not confirmed
 *                            a successful start yet
 *  - `.update-result.json`  outcome of the last apply, read by the admin UI
 *  - `.update-backup/<v>/`  the code (and config snapshot) the update replaced
 */
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const STAGING_DIR = '.update-staging';
const BACKUP_DIR = '.update-backup';
const PENDING_FILE = '.update-pending.json';
const ATTEMPT_FILE = '.update-attempt.json';
const RESULT_FILE = '.update-result.json';
const BACKUP_META_FILE = 'backup-meta.json';
const CONFIG_SNAPSHOT_DIR = 'config-snapshot';

/**
 * Version of the launcher's update handling. The launcher puts it into the
 * server's environment as `IHUB_LAUNCHER_PROTOCOL`; a server started by an
 * older launcher sees none and falls back to swapping in-process.
 */
const LAUNCHER_PROTOCOL = 2;

/** Failed starts of an updated server before the launcher restores the previous version. */
const MAX_FAILED_STARTS = 3;

/** The versioned launcher script in the installation root. */
const LAUNCHER_SCRIPT_PATTERN = /^ihub-apps-v.*-(linux|macos|win\.bat)$/;

/** Error codes a rename hits on Windows while a scanner or indexer holds a file. */
const TRANSIENT_FS_ERRORS = new Set(['EBUSY', 'EPERM', 'EACCES', 'ENOTEMPTY', 'EMFILE']);

function nodeBinaryName(platform) {
  return platform === 'windows' ? 'node.exe' : 'node';
}

/**
 * Paths in the installation root an update replaces. Everything else
 * (`contents/`, `config.env`, `logs/`, the Windows service XML an admin may
 * have customised) stays as it is.
 *
 * @param {string} platform - `linux`, `macos` or `windows`
 * @returns {string[]}
 */
function getReplacePaths(platform) {
  return [
    'server',
    'shared',
    'public',
    'docs',
    'browser-extension',
    'launcher.cjs',
    nodeBinaryName(platform),
    'version.txt',
    'update-manifest.json',
    'update-manifest.json.sig'
  ];
}

/**
 * The platform of this installation, from its launcher script's name, falling
 * back to the operating system.
 *
 * @param {string} rootDir
 * @returns {'linux'|'macos'|'windows'}
 */
function detectPlatform(rootDir) {
  try {
    const launcher = fs.readdirSync(rootDir).find(f => LAUNCHER_SCRIPT_PATTERN.test(f));
    if (launcher) {
      if (launcher.endsWith('-linux')) return 'linux';
      if (launcher.endsWith('-macos')) return 'macos';
      if (launcher.endsWith('-win.bat')) return 'windows';
    }
  } catch {
    // fall back to the operating system
  }
  if (process.platform === 'darwin') return 'macos';
  if (process.platform === 'win32') return 'windows';
  return 'linux';
}

function sleepSync(ms) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

/**
 * `renameSync` that retries while Windows reports a file as busy (antivirus
 * scanning a freshly written file, the search indexer, a lingering handle).
 */
function renameWithRetry(from, to, attempts = 6) {
  for (let attempt = 1; ; attempt++) {
    try {
      fs.renameSync(from, to);
      return;
    } catch (error) {
      if (attempt >= attempts || !TRANSIENT_FS_ERRORS.has(error.code)) throw error;
      sleepSync(100 * 2 ** attempt);
    }
  }
}

function readJson(file) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    return null;
  }
}

function writeJson(file, data, mode) {
  const tmp = `${file}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(data, null, 2), mode ? { mode } : undefined);
  renameWithRetry(tmp, file);
}

function removeFile(file) {
  try {
    fs.rmSync(file, { force: true });
  } catch {
    // ignore
  }
}

/** A version string reduced to characters that are safe as a directory name. */
function safeVersionDir(version) {
  const safe = String(version || '').replace(/[^a-zA-Z0-9._-]/g, '');
  if (!safe || safe === '.' || safe === '..') return 'unknown';
  return safe;
}

function readVersion(rootDir) {
  try {
    return fs.readFileSync(path.join(rootDir, 'version.txt'), 'utf8').trim() || null;
  } catch {
    return null;
  }
}

/**
 * Move the staged release into the installation root, moving what it replaces
 * into `backupDir`. Undoes every move it made when one fails, so the
 * installation is left as it was.
 *
 * @param {string} rootDir
 * @param {Object} options
 * @param {string} options.backupDir - Created if missing; existing entries for
 *   the replaced paths (a failed earlier attempt) are removed first
 * @param {string} [options.stagingDir]
 * @param {string} [options.platform]
 * @returns {{ replaced: string[] }}
 */
function swapInStaged(rootDir, { backupDir, stagingDir, platform } = {}) {
  const staging = stagingDir || path.join(rootDir, STAGING_DIR);
  const plat = platform || detectPlatform(rootDir);
  if (!fs.existsSync(staging)) {
    throw new Error('No staged update found');
  }
  fs.mkdirSync(backupDir, { recursive: true });

  // Undo log: [from, to] pairs, replayed backwards on failure.
  const moves = [];
  const move = (from, to) => {
    renameWithRetry(from, to);
    moves.push([from, to]);
  };

  try {
    const replaced = [];
    for (const rel of getReplacePaths(plat)) {
      const staged = path.join(staging, rel);
      if (!fs.existsSync(staged)) continue;
      const current = path.join(rootDir, rel);
      const backup = path.join(backupDir, rel);
      fs.rmSync(backup, { recursive: true, force: true });
      if (fs.existsSync(current)) move(current, backup);
      move(staged, current);
      replaced.push(rel);
    }

    // The launcher script carries the version in its name, so the old one is
    // moved away even when the new one has a different name.
    const rootFiles = fs.readdirSync(rootDir);
    const stagedFiles = fs.readdirSync(staging);
    const currentLauncher = rootFiles.find(f => LAUNCHER_SCRIPT_PATTERN.test(f));
    const newLauncher = stagedFiles.find(f => LAUNCHER_SCRIPT_PATTERN.test(f));
    if (newLauncher) {
      if (currentLauncher)
        move(path.join(rootDir, currentLauncher), path.join(backupDir, currentLauncher));
      move(path.join(staging, newLauncher), path.join(rootDir, newLauncher));
      replaced.push(newLauncher);
    }

    if (plat !== 'windows') {
      for (const executable of [nodeBinaryName(plat), newLauncher]) {
        if (!executable) continue;
        const file = path.join(rootDir, executable);
        if (fs.existsSync(file)) fs.chmodSync(file, 0o755);
      }
    }

    fs.rmSync(staging, { recursive: true, force: true });
    return { replaced };
  } catch (error) {
    for (const [from, to] of moves.reverse()) {
      try {
        if (fs.existsSync(from)) fs.rmSync(from, { recursive: true, force: true });
        renameWithRetry(to, from);
      } catch (undoError) {
        error.message += `; undoing the move of ${path.basename(from)} failed: ${undoError.message}`;
      }
    }
    throw error;
  }
}

/**
 * Restore the code kept in a backup directory, then remove the backup.
 *
 * @param {string} rootDir
 * @param {string} backupDir
 * @param {Object} [options]
 * @param {string} [options.platform]
 * @param {string} [options.contentsDir] - With `restoreConfig`, the contents directory
 * @param {boolean} [options.restoreConfig] - Also put back the configuration
 *   snapshot taken before the update (config changes made since are lost)
 * @returns {{ restoredVersion: string|null, configRestored: boolean }}
 */
function restoreBackup(rootDir, backupDir, { platform, contentsDir, restoreConfig = false } = {}) {
  const plat = platform || detectPlatform(rootDir);
  if (!fs.existsSync(backupDir)) throw new Error('No backup available for rollback');

  for (const rel of getReplacePaths(plat)) {
    const backup = path.join(backupDir, rel);
    if (!fs.existsSync(backup)) continue;
    const current = path.join(rootDir, rel);
    fs.rmSync(current, { recursive: true, force: true });
    renameWithRetry(backup, current);
  }

  const backupLauncher = fs.readdirSync(backupDir).find(f => LAUNCHER_SCRIPT_PATTERN.test(f));
  if (backupLauncher) {
    const currentLauncher = fs.readdirSync(rootDir).find(f => LAUNCHER_SCRIPT_PATTERN.test(f));
    if (currentLauncher) fs.rmSync(path.join(rootDir, currentLauncher), { force: true });
    renameWithRetry(path.join(backupDir, backupLauncher), path.join(rootDir, backupLauncher));
    if (plat !== 'windows') fs.chmodSync(path.join(rootDir, backupLauncher), 0o755);
  }

  let configRestored = false;
  if (restoreConfig) {
    configRestored = restoreConfigSnapshot(backupDir, contentsDir);
  }

  fs.rmSync(backupDir, { recursive: true, force: true });
  const backupBase = path.dirname(backupDir);
  try {
    if (fs.readdirSync(backupBase).length === 0) fs.rmSync(backupBase, { recursive: true });
  } catch {
    // ignore
  }
  return { restoredVersion: readVersion(rootDir), configRestored };
}

/**
 * Copy `contents/config` and the migration history into the backup directory,
 * so a rollback can put back the configuration the old code understands
 * (migrations are forward-only). `contents/.encryption-key` is not under
 * `config/` and is never copied. The snapshot directory is private (0700).
 *
 * @param {string} backupDir
 * @param {string} contentsDir
 * @returns {{ bytes: number }}
 */
function writeConfigSnapshot(backupDir, contentsDir) {
  const snapshot = path.join(backupDir, CONFIG_SNAPSHOT_DIR);
  fs.rmSync(snapshot, { recursive: true, force: true });
  fs.mkdirSync(snapshot, { recursive: true, mode: 0o700 });
  fs.chmodSync(snapshot, 0o700);
  const configDir = path.join(contentsDir, 'config');
  if (fs.existsSync(configDir)) {
    fs.cpSync(configDir, path.join(snapshot, 'config'), { recursive: true });
  }
  const history = path.join(contentsDir, '.migration-history.json');
  if (fs.existsSync(history)) {
    fs.copyFileSync(history, path.join(snapshot, '.migration-history.json'));
  }
  return { bytes: directorySize(snapshot) };
}

function restoreConfigSnapshot(backupDir, contentsDir) {
  const snapshot = path.join(backupDir, CONFIG_SNAPSHOT_DIR);
  if (!contentsDir || !fs.existsSync(path.join(snapshot, 'config'))) return false;
  const liveConfig = path.join(contentsDir, 'config');
  const displaced = `${liveConfig}.before-rollback-${Date.now()}`;
  if (fs.existsSync(liveConfig)) renameWithRetry(liveConfig, displaced);
  try {
    renameWithRetry(path.join(snapshot, 'config'), liveConfig);
  } catch (error) {
    if (fs.existsSync(displaced)) renameWithRetry(displaced, liveConfig);
    throw error;
  }
  fs.rmSync(displaced, { recursive: true, force: true });
  const history = path.join(snapshot, '.migration-history.json');
  if (fs.existsSync(history)) {
    fs.copyFileSync(history, path.join(contentsDir, '.migration-history.json'));
  }
  return true;
}

function directorySize(dir) {
  let total = 0;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) total += directorySize(full);
    else if (entry.isFile()) total += fs.statSync(full).size;
  }
  return total;
}

/**
 * Backups, newest first (by the time they were taken, not by version string:
 * `5.10.0` sorts before `5.9.0`).
 *
 * @param {string} rootDir
 * @returns {Array<{ dir: string, version: string|null, createdAt: number, hasConfigSnapshot: boolean }>}
 */
function listBackups(rootDir) {
  const base = path.join(rootDir, BACKUP_DIR);
  let names;
  try {
    names = fs.readdirSync(base, { withFileTypes: true });
  } catch {
    return [];
  }
  const backups = [];
  for (const entry of names) {
    if (!entry.isDirectory()) continue;
    const dir = path.join(base, entry.name);
    const meta = readJson(path.join(dir, BACKUP_META_FILE)) || {};
    let createdAt = Date.parse(meta.createdAt || '') || 0;
    if (!createdAt) {
      try {
        createdAt = fs.statSync(dir).mtimeMs;
      } catch {
        // ignore
      }
    }
    let version = meta.version || null;
    if (!version) {
      try {
        version = fs.readFileSync(path.join(dir, 'version.txt'), 'utf8').trim() || null;
      } catch {
        // ignore
      }
    }
    backups.push({
      dir,
      version,
      createdAt,
      targetVersion: meta.targetVersion || null,
      hasConfigSnapshot: fs.existsSync(path.join(dir, CONFIG_SNAPSHOT_DIR, 'config'))
    });
  }
  return backups.sort((a, b) => b.createdAt - a.createdAt);
}

/**
 * A fresh backup directory for the running version, with its metadata.
 * Removes a stale backup of the same version (an earlier failed attempt).
 */
function prepareBackupDir(rootDir, { version, targetVersion }) {
  const dir = path.join(rootDir, BACKUP_DIR, safeVersionDir(version));
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(dir, { recursive: true });
  writeJson(path.join(dir, BACKUP_META_FILE), {
    version,
    targetVersion: targetVersion || null,
    createdAt: new Date().toISOString()
  });
  return dir;
}

const pendingPath = rootDir => path.join(rootDir, PENDING_FILE);
const attemptPath = rootDir => path.join(rootDir, ATTEMPT_FILE);
const resultPath = rootDir => path.join(rootDir, RESULT_FILE);

function readPending(rootDir) {
  return readJson(pendingPath(rootDir));
}

/**
 * Ask the launcher to apply the staged release on the next start.
 * @param {string} rootDir
 * @param {{ targetVersion: string, previousVersion: string, backupDir: string }} pending
 */
function writePending(rootDir, pending) {
  writeJson(pendingPath(rootDir), { ...pending, requestedAt: new Date().toISOString() });
}

function clearPending(rootDir) {
  removeFile(pendingPath(rootDir));
}

function readAttempt(rootDir) {
  return readJson(attemptPath(rootDir));
}

function writeAttempt(rootDir, attempt) {
  writeJson(attemptPath(rootDir), attempt);
}

function readResult(rootDir) {
  return readJson(resultPath(rootDir));
}

function writeResult(rootDir, result) {
  writeJson(resultPath(rootDir), { ...result, finishedAt: new Date().toISOString() });
}

/**
 * Apply a pending update, if there is one. Called by the launcher before it
 * starts the server.
 *
 * The pending marker is removed before anything is moved, so a crash in the
 * middle cannot make every following start try again.
 *
 * @param {string} rootDir
 * @param {{ log?: Function }} [options]
 * @returns {{ applied: boolean, error?: string, targetVersion?: string }}
 */
function applyPendingUpdate(rootDir, { log = () => {}, contentsDir } = {}) {
  const pending = readPending(rootDir);
  if (!pending) return { applied: false };
  clearPending(rootDir);

  const previousVersion = readVersion(rootDir);
  const backupDir =
    pending.backupDir && path.isAbsolute(pending.backupDir)
      ? pending.backupDir
      : path.join(rootDir, BACKUP_DIR, safeVersionDir(previousVersion));
  const contents = pending.contentsDir || contentsDir;
  // The backup directory must be ours: inside .update-backup of this root.
  const backupBase = path.join(rootDir, BACKUP_DIR) + path.sep;
  if (!path.resolve(backupDir).startsWith(backupBase)) {
    const reason = 'Pending update names a backup directory outside .update-backup';
    writeResult(rootDir, {
      status: 'failed',
      targetVersion: pending.targetVersion,
      previousVersion,
      reason
    });
    log(reason);
    return { applied: false, error: reason };
  }

  if (pending.action === 'rollback') {
    log(`Rolling back ${previousVersion} -> ${pending.targetVersion}`);
    try {
      const { restoredVersion, configRestored } = restoreBackup(rootDir, backupDir, {
        contentsDir: contents,
        restoreConfig: pending.restoreConfig === true
      });
      writeResult(rootDir, {
        status: 'rolled-back',
        manual: true,
        targetVersion: restoredVersion,
        previousVersion,
        configRestored
      });
      return { applied: true, rolledBack: true, targetVersion: restoredVersion };
    } catch (error) {
      const reason = `Rolling back failed: ${error.message}. The backup is in ${backupDir}.`;
      writeResult(rootDir, {
        status: 'failed',
        targetVersion: pending.targetVersion,
        previousVersion,
        reason
      });
      log(reason);
      return { applied: false, error: reason };
    }
  }

  log(`Applying update ${previousVersion} -> ${pending.targetVersion}`);
  try {
    swapInStaged(rootDir, { backupDir });
  } catch (error) {
    const reason = `Applying the update failed, the previous version stays installed: ${error.message}`;
    writeResult(rootDir, {
      status: 'failed',
      targetVersion: pending.targetVersion,
      previousVersion,
      reason
    });
    log(reason);
    return { applied: false, error: reason };
  }
  writeAttempt(rootDir, {
    targetVersion: pending.targetVersion,
    previousVersion,
    backupDir,
    contentsDir: contents || null,
    failedStarts: 0,
    appliedAt: new Date().toISOString()
  });
  log(`Update to ${pending.targetVersion} applied; waiting for the server to start`);
  return { applied: true, targetVersion: pending.targetVersion };
}

/**
 * Record that the server exited. While an applied update has not been
 * confirmed, a failing exit counts as a failed start; after
 * {@link MAX_FAILED_STARTS} of them the previous version is restored.
 *
 * @param {string} rootDir
 * @param {number|null} exitCode
 * @param {{ log?: Function, contentsDir?: string }} [options]
 * @returns {'none'|'retry'|'rolled-back'} `none`: no update is being tried, the
 *   launcher behaves as before; otherwise it starts the server again
 */
function recordServerExit(rootDir, exitCode, { log = () => {}, contentsDir } = {}) {
  const attempt = readAttempt(rootDir);
  if (!attempt || exitCode === 0 || exitCode === 75) return 'none';

  attempt.failedStarts = (attempt.failedStarts || 0) + 1;
  attempt.lastExitCode = exitCode;
  if (attempt.failedStarts < MAX_FAILED_STARTS) {
    writeAttempt(rootDir, attempt);
    log(
      `Updated server exited with code ${exitCode} before it finished starting ` +
        `(${attempt.failedStarts}/${MAX_FAILED_STARTS}), trying again`
    );
    return 'retry';
  }

  const reason =
    `Version ${attempt.targetVersion} failed to start ${attempt.failedStarts} times ` +
    `(last exit code ${exitCode}); version ${attempt.previousVersion} was restored`;
  log(reason);
  removeFile(attemptPath(rootDir));
  // The new version's migrations may have run during the failed starts, and
  // nothing has been served since: put the configuration back as well.
  const contents = attempt.contentsDir || contentsDir;
  try {
    restoreBackup(rootDir, attempt.backupDir, {
      contentsDir: contents,
      restoreConfig: Boolean(contents)
    });
    writeResult(rootDir, {
      status: 'rolled-back',
      targetVersion: attempt.targetVersion,
      previousVersion: attempt.previousVersion,
      reason
    });
  } catch (error) {
    writeResult(rootDir, {
      status: 'failed',
      targetVersion: attempt.targetVersion,
      previousVersion: attempt.previousVersion,
      reason: `${reason}, but restoring it failed: ${error.message}. The backup is in ${attempt.backupDir}.`
    });
    log(`Restoring the previous version failed: ${error.message}`);
  }
  return 'rolled-back';
}

/**
 * Called by the server once it is listening: an update that got this far worked.
 *
 * @param {string} rootDir
 * @param {string} runningVersion
 * @returns {Object|null} The result written, if an update was being confirmed
 */
function confirmUpdateAttempt(rootDir, runningVersion) {
  const attempt = readAttempt(rootDir);
  if (!attempt) return null;
  removeFile(attemptPath(rootDir));
  const result = {
    status: runningVersion === attempt.targetVersion ? 'success' : 'failed',
    targetVersion: attempt.targetVersion,
    previousVersion: attempt.previousVersion,
    runningVersion,
    ...(runningVersion !== attempt.targetVersion && {
      reason: `Expected version ${attempt.targetVersion} after the update, but ${runningVersion} started`
    })
  };
  writeResult(rootDir, result);
  return result;
}

module.exports = {
  STAGING_DIR,
  BACKUP_DIR,
  PENDING_FILE,
  ATTEMPT_FILE,
  RESULT_FILE,
  CONFIG_SNAPSHOT_DIR,
  LAUNCHER_PROTOCOL,
  MAX_FAILED_STARTS,
  LAUNCHER_SCRIPT_PATTERN,
  getReplacePaths,
  detectPlatform,
  nodeBinaryName,
  safeVersionDir,
  readVersion,
  swapInStaged,
  restoreBackup,
  writeConfigSnapshot,
  listBackups,
  prepareBackupDir,
  readPending,
  writePending,
  clearPending,
  readAttempt,
  writeAttempt,
  readResult,
  writeResult,
  applyPendingUpdate,
  recordServerExit,
  confirmUpdateAttempt
};
